/**
 * scripts/api/sync-contract.mjs
 *
 * The API repo owns the contract (api/openapi.json). This script mirrors it
 * into the modeller and generates the TypeScript types from it:
 *
 *   src/api/openapi.json   exact copy of the API's committed contract
 *   src/api/schema.d.ts    types generated by openapi-typescript
 *
 *   node scripts/api/sync-contract.mjs [--api ../api/openapi.json]   write both
 *   node scripts/api/sync-contract.mjs --check                        fail if either is stale
 *                                                                     (compares against the committed copy;
 *                                                                      add --api to compare with the API repo)
 */
import { spawnSync } from 'node:child_process';
import { copyFileSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..');
const args = process.argv.slice(2);
const opt = (n) => { const i = args.indexOf(n); return i >= 0 ? args[i + 1] : undefined; };
const check = args.includes('--check');
const apiSpec = opt('--api') ? resolve(opt('--api')) : null;

const spec = join(root, 'src/api/openapi.json');
const types = join(root, 'src/api/schema.d.ts');
const cli = join(root, 'node_modules/openapi-typescript/bin/cli.js');

function generate(from, to) {
  const r = spawnSync(process.execPath, [cli, from, '-o', to], { encoding: 'utf8' });
  if (r.status !== 0) { console.error(r.stderr || r.stdout); process.exit(1); }
}
const read = (p) => readFileSync(p, 'utf8');
const fail = (msg) => { console.error(`CONTRACT CHECK FAILED: ${msg}`); process.exit(1); };

if (apiSpec && !existsSync(apiSpec)) fail(`API contract not found: ${apiSpec}`);

if (check) {
  if (apiSpec && read(apiSpec) !== read(spec)) fail('src/api/openapi.json differs from the API repo — run `npm run api:types`');
  const tmp = mkdtempSync(join(tmpdir(), 'contract-'));
  generate(spec, join(tmp, 'schema.d.ts'));
  const stale = read(join(tmp, 'schema.d.ts')) !== read(types);
  rmSync(tmp, { recursive: true, force: true });
  if (stale) fail('src/api/schema.d.ts is stale — run `npm run api:types`');
  console.log('CONTRACT CHECK OK — openapi.json and schema.d.ts are in sync');
} else {
  if (!apiSpec) fail('pass --api <path to api/openapi.json> (npm run api:types uses ../api/openapi.json)');
  copyFileSync(apiSpec, spec);
  generate(spec, types);
  console.log('contract synced: src/api/openapi.json + src/api/schema.d.ts');
}
